@import url('https://fonts.googleapis.com/css2?family=IBM+Plex+Mono:wght@400;500;600;700&display=swap');

/* Windows 95 DNA — silver bevels, navy title bars, teal desktop, hard pixels */
.theme-windows95-dna {
  --bg: oklch(0.543 0.093 194.8);
  --surface: oklch(0.808 0 0);
  --surface-2: oklch(0.904 0 0);
  --fg: oklch(0.000 0 0);
  --fg-muted: oklch(0.4 0 0);
  --accent: oklch(0.271 0.188 264.1);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.543 0.093 194.8);
  --line: oklch(0.600 0 0);
  --success: oklch(0.520 0.177 142.5);
  --warning: oklch(0.581 0.127 109.8);
  --danger: oklch(0.463 0.190 29.2);
  --radius: 0px;
  --radius-sm: 0px;
  --radius-lg: 0px;
  --radius-pill: 0px;
  --shadow-1: inset -1px -1px 0 oklch(0 0 0), inset 1px 1px 0 oklch(1 0 0), inset -2px -2px 0 oklch(0.5 0 0), inset 2px 2px 0 oklch(0.87 0 0);
  --shadow-2: inset -1px -1px 0 oklch(0 0 0), inset 1px 1px 0 oklch(1 0 0);
  --shadow-3: 4px 4px 0 oklch(0 0 0 / 40%);
  --glow: 0 0 0 1px dotted oklch(0 0 0);
  --border-width: 2px;
  --blur-amount: 0px;
  --font-display: "Tahoma", "MS Sans Serif", "Segoe UI", sans-serif;
  --font-body: "Tahoma", "MS Sans Serif", "Segoe UI", sans-serif;
  --font-mono: "IBM Plex Mono", monospace;
  --tracking-display: 0em;
  --label-transform: none;
  --label-tracking: 0.02em;

  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}

.theme-windows95-dna h1,
.theme-windows95-dna h2,
.theme-windows95-dna h3 {
  font-family: var(--font-display);
  letter-spacing: var(--tracking-display);
}

/* signature */
.theme-windows95-dna button:active { box-shadow: inset 1px 1px 0 oklch(0 0 0), inset -1px -1px 0 oklch(1 0 0); }
.theme-windows95-dna h2 { background: linear-gradient(90deg, var(--accent), oklch(0.45 0.19 262)); color: #ffffff; padding: 0.2rem 0.6rem; font-size: 1rem; }
.theme-windows95-dna * { transition: none !important; }

/* depth */
.theme-windows95-dna thead th { background: var(--surface); box-shadow: inset -1px -1px 0 oklch(0 0 0), inset 1px 1px 0 oklch(1 0 0), inset -2px -2px 0 oklch(0.5 0 0), inset 2px 2px 0 oklch(0.87 0 0); font-weight: 400; padding: 0.25rem 0.5rem; border: none; }
.theme-windows95-dna td { border-bottom: 1px solid var(--surface-2); background: oklch(1 0 0); }
.theme-windows95-dna tbody tr:hover td { background: var(--accent); color: var(--accent-fg); }
.theme-windows95-dna input, .theme-windows95-dna textarea, .theme-windows95-dna select { background: oklch(1 0 0); border: none; border-radius: 0; box-shadow: inset 1px 1px 0 oklch(0.5 0 0), inset -1px -1px 0 oklch(1 0 0), inset 2px 2px 0 oklch(0 0 0 / 55%), inset -2px -2px 0 oklch(0.87 0 0); padding: 0.3rem 0.5rem; }
.theme-windows95-dna input:focus-visible, .theme-windows95-dna textarea:focus-visible, .theme-windows95-dna select:focus-visible { outline: 1px dotted oklch(0 0 0); outline-offset: -4px; }
.theme-windows95-dna kbd { font-family: var(--font-body); font-size: 0.85em; background: var(--surface); box-shadow: inset -1px -1px 0 oklch(0 0 0), inset 1px 1px 0 oklch(1 0 0), inset -2px -2px 0 oklch(0.5 0 0), inset 2px 2px 0 oklch(0.87 0 0); padding: 0.15em 0.5em; }
.theme-windows95-dna a { color: oklch(0.36 0.25 264.1); text-decoration: underline; }
.theme-windows95-dna a:hover { color: oklch(0.463 0.190 29.2); }
.theme-windows95-dna ::selection { background: var(--accent); color: var(--accent-fg); }
.theme-windows95-dna ::-webkit-scrollbar { width: 16px; height: 16px; }
.theme-windows95-dna ::-webkit-scrollbar-track { background-color: var(--surface-2); background-image: linear-gradient(45deg, oklch(0.808 0 0) 25%, transparent 25%, transparent 75%, oklch(0.808 0 0) 75%), linear-gradient(45deg, oklch(0.808 0 0) 25%, transparent 25%, transparent 75%, oklch(0.808 0 0) 75%); background-size: 2px 2px; background-position: 0 0, 1px 1px; }
.theme-windows95-dna ::-webkit-scrollbar-thumb { background: var(--surface); border-radius: 0; box-shadow: inset -1px -1px 0 oklch(0 0 0), inset 1px 1px 0 oklch(1 0 0), inset -2px -2px 0 oklch(0.5 0 0), inset 2px 2px 0 oklch(0.87 0 0); }
.theme-windows95-dna .label-caps { background: var(--surface); padding: 0 0.35em; }
.theme-windows95-dna .themed-border { border: none; box-shadow: inset -1px -1px 0 oklch(1 0 0), inset 1px 1px 0 oklch(0.5 0 0), inset -2px -2px 0 oklch(0.5 0 0), inset 2px 2px 0 oklch(1 0 0); padding: 0.75rem; }
.theme-windows95-dna hr { border: none; border-top: 1px solid oklch(0.5 0 0); border-bottom: 1px solid oklch(1 0 0); }

/* alt mode: High Contrast scheme — Accessibility Options, black desktop, white chrome */
.theme-windows95-dna.alt-mode {
  --bg: oklch(0.000 0 0);
  --surface: oklch(0.13 0 0);
  --surface-2: oklch(0.22 0 0);
  --fg: oklch(1.000 0 0);
  --fg-muted: oklch(0.78 0 0);
  --accent: oklch(0.55 0.23 301);
  --accent-fg: oklch(1.000 0 0);
  --accent-2: oklch(0.90 0.17 105);
  --line: oklch(1.000 0 0);
  --shadow-1: inset -1px -1px 0 oklch(0.45 0 0), inset 1px 1px 0 oklch(1 0 0);
  --shadow-2: inset -1px -1px 0 oklch(0.45 0 0), inset 1px 1px 0 oklch(1 0 0);
  --shadow-3: 4px 4px 0 oklch(1 0 0 / 25%);
  background-image: none;
}
.theme-windows95-dna.alt-mode h2 { background: linear-gradient(90deg, var(--accent), oklch(0.35 0.18 301)); }
.theme-windows95-dna.alt-mode thead th { background: var(--surface-2); color: var(--fg); box-shadow: inset -1px -1px 0 oklch(0.45 0 0), inset 1px 1px 0 oklch(1 0 0); }
.theme-windows95-dna.alt-mode td { background: var(--bg); border-bottom-color: var(--surface-2); }
.theme-windows95-dna.alt-mode tbody tr:hover td { background: oklch(0.90 0.17 105); color: oklch(0 0 0); }
.theme-windows95-dna.alt-mode input, .theme-windows95-dna.alt-mode textarea, .theme-windows95-dna.alt-mode select { background: oklch(0 0 0); color: var(--fg); box-shadow: inset 0 0 0 2px oklch(1 0 0); }
.theme-windows95-dna.alt-mode a { color: oklch(0.90 0.17 105); }
.theme-windows95-dna.alt-mode a:hover { color: oklch(0.85 0.15 195); }
.theme-windows95-dna.alt-mode kbd { background: var(--surface-2); box-shadow: inset -1px -1px 0 oklch(0.45 0 0), inset 1px 1px 0 oklch(1 0 0); }
.theme-windows95-dna.alt-mode ::selection { background: oklch(0.90 0.17 105); color: oklch(0 0 0); }
.theme-windows95-dna.alt-mode ::-webkit-scrollbar-track { background-color: oklch(0 0 0); background-image: none; border: 1px solid oklch(1 0 0); }
.theme-windows95-dna.alt-mode ::-webkit-scrollbar-thumb { background: var(--surface-2); box-shadow: inset -1px -1px 0 oklch(0.45 0 0), inset 1px 1px 0 oklch(1 0 0); }

/* Bridge shadcn semantic variables to the theme tokens so stock shadcn/ui
   components are skinned by the theme. Scope-safe: applies inside the theme
   class only. */
[class*="theme-"] {
  --background: var(--bg);
  --foreground: var(--fg);
  --card: var(--surface);
  --card-foreground: var(--fg);
  --popover: var(--surface);
  --popover-foreground: var(--fg);
  --primary: var(--accent);
  --primary-foreground: var(--accent-fg);
  --secondary: var(--surface-2);
  --secondary-foreground: var(--fg);
  --muted: var(--surface-2);
  --muted-foreground: var(--fg-muted);
  --accent-foreground: var(--accent-fg);
  --border: var(--line);
  --input: var(--line);
  --ring: var(--accent);
  --destructive: var(--danger);
  --destructive-foreground: var(--accent-fg);

  /* Full app surface: sidebar, charts, app-level font + shadow + tracking vars.
     These are what real products (shadcn full kit, RootCX-style UI kits) consume —
     without them a retrofit looks half-themed. */
  --sidebar: var(--surface-2);
  --sidebar-foreground: var(--fg);
  --sidebar-primary: var(--accent);
  --sidebar-primary-foreground: var(--accent-fg);
  --sidebar-accent: color-mix(in oklab, var(--accent) 12%, var(--surface-2));
  --sidebar-accent-foreground: var(--fg);
  --sidebar-border: var(--line);
  --sidebar-ring: var(--accent);

  --chart-1: var(--accent);
  --chart-2: var(--accent-2);
  --chart-3: var(--success);
  --chart-4: var(--warning);
  --chart-5: var(--danger);

  --font-sans: var(--font-body);
  --font-heading: var(--font-display);
  --font-serif: var(--font-display);

  --shadow-2xs: var(--shadow-1);
  --shadow-xs: var(--shadow-1);
  --shadow-sm: var(--shadow-1);
  --shadow: var(--shadow-2);
  --shadow-md: var(--shadow-2);
  --shadow-lg: var(--shadow-3);
  --shadow-xl: var(--shadow-3);
  --shadow-2xl: var(--shadow-3);

  --tracking-normal: 0em;
}

/* Base experience: make the theme own the canvas and native elements even in
   apps that never adopted semantic classes. Scoped to the theme wrapper. */
[class*="theme-"] {
  background-color: var(--bg);
  color: var(--fg);
  font-family: var(--font-body);
}
[class*="theme-"] :is(h1, h2, h3, h4) { font-family: var(--font-display); }
[class*="theme-"] :is(code, pre, kbd, samp) { font-family: var(--font-mono); }
[class*="theme-"] ::selection { background: color-mix(in oklab, var(--accent) 30%, transparent); }

/* OPT-IN HARD MODE — add "sf-enforce" beside the theme class when the host app
   bakes font/shadow/radius literals into its compiled utilities (a var bridge
   cannot beat a literal). Targeted !important, fonts and surfaces only. */
[class*="theme-"].sf-enforce { font-family: var(--font-body) !important; }
[class*="theme-"].sf-enforce :is(h1, h2, h3, h4, [class*="font-heading"]) {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
/* Data stays data: metrics/KPIs keep the body face with aligned lining figures.
   The display face is for headlines ONLY — never on numbers. Opt specific
   elements INTO the display face with data-sf="display". */
[class*="theme-"] :is([class*="text-2xl"], [class*="text-3xl"], [class*="text-4xl"], [class*="text-5xl"]) {
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce [data-sf="display"] {
  font-family: var(--font-display) !important;
  letter-spacing: var(--tracking-display) !important;
}
[class*="theme-"] :is(.sf-num, [data-sf="num"]) {
  font-family: var(--font-body) !important;
  font-variant-numeric: lining-nums tabular-nums;
}
[class*="theme-"].sf-enforce :is(button, [role="button"]) { font-family: var(--font-ui, var(--font-body)) !important; }
[class*="theme-"].sf-enforce :is(code, pre, kbd) { font-family: var(--font-mono) !important; }
[class*="theme-"].sf-enforce :is(.bg-card, [class*="card"]) {
  box-shadow: var(--shadow-2) !important;
  border-radius: var(--radius-lg) !important;
  border: var(--border-width) solid var(--line) !important;
}
[class*="theme-"].sf-enforce :is([class*="shadow-sm"], [class*="shadow-md"]) { box-shadow: var(--shadow-1) !important; }
[class*="theme-"].sf-enforce :is([class*="shadow-lg"], [class*="shadow-xl"]) { box-shadow: var(--shadow-3) !important; }
